  pyOut.error ? `ERROR: ${pyOut.error}` : `python ok ${jsToPyOk}/3; tamper -> ${jsToPyTamper ? (jsToPyTamper.ok ? 'SILENTLY OK (BAD)' : jsToPyTamper.reasons.join(',')) : 'n/a'}`);

