try {
  pyMint = JSON.parse(execFileSync('python3', [join(HERE, 'py_bridge.py'), 'mint', '3'],
    { encoding: 'utf8', timeout: 60000,
      env: { ...process.env, JEVDATA_DIR: '/home/z/my-project/foreign-refs/jev-quilt' } }));
