  bridge.translator.digestAgreeCount === bridge.corpusSize &&
  bridge.probeFindings.find((p) => p.id === 'non-finite-NaN')?.stoneOut === '{"a":null}' &&
  bridge.probeFindings.find((p) => p.id === 'non-finite-NaN')?.jcsThrew === true,
