    expectLeafIndex: 2857259740,
    expectPathHashes: 26,
    expectArtifactSha256: '94aa82cdde3a717dc9aa68729d9ef96a398daa39d2d83204edea26f5ba75b1e5',
    logKeyFingerprint: 'dce5ef715502ec9f3cdfd11f8cc384b31a6141023d3e7595e9908a81cb6241bd',
